def shell_sort(arr):
    """Sort a list of integers in-place using shell sort.

    Args:
        arr: A list of integers.

    Returns:
        None. The input list is sorted in-place.
    """
    n = len(arr)
    for i in range(n):
        # Last i elements are already in place
        for j in range(n - i - 1):
            if arr[j] > arr[j + 1]:
                arr[j], arr[j + 1] = arr[j + 1], arr[j]

def sumofFactors(num):
    """Return the sum of all even factors of a given integer.

    Args:
        num: An integer.

    Returns:
        An integer.
    """
    if num == 0:
        return 0
    if num % 2 == 0:
        return num * sumofFactors(num - 1)
    else:
        return num * sumofFactors(num - 1) + 1

