    Args:
        n (int): The position in the sequence.

    Returns:
        int: The nth catalan number.
    """
    if n <= 0:
        raise ValueError("n must be a positive integer")
    if n == 1:
        return 1
    return catalan_number(n - 1) + catalan_number(n - 2)

def sum_Of_product(n):
    """Return the sum of the product of consecutive binomial co-efficients.

    Args:
        n: An integer.

    Returns:
        The sum of the product of consecutive binomial co-efficients.
    """
    if n < 0:
        raise ValueError("n must be non-negative")
    if n == 0:
        return 1
    if n == 1:
        return 1
    return n * sum_Of_product(n - 1)

