def is_decimal(num: str) -> bool:
    """Check if a string of digits is a decimal number with a precision of 2.

    Args:
        num: A string containing digits (0-9).

    Returns:
        True if the string is a decimal number with a precision of 2,
        False otherwise.
    """
    if not num:
        return False
    if len(num) == 1:
        return True
    if num[0] == '0':
        return False
    if num[0] == '-':
        return False
    if num[0] == '+':
        return False
    if num[0] == '*':
        return False
    if num[0] == '/':
        return False
    if num[0] == '0':
        return False
    return True

