def is_polite(n: int) -> bool:
    """Return True if n is a polite number, False otherwise."""
    if n < 1:
        return False
    if n == 1:
        return True
    if n % 2 == 0:
        return False
    return is_polite(n // 2)

def nth_polite(n: int) -> int:
    """Return the nth polite number. geeksforgeeks.org/n-th-polite-number/
    assert is_polite(n) == n
    """
    if is_polite(n):
        return n
    return nth_polite(n - 1) + 1

def check_expression(expression):
    """Check if the given expression is balanced or not.

    Args:
        expression: A string representing a mathematical expression.

    Returns:
        True if the expression is balanced, False otherwise.
    """
    stack = []
    for char in expression:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack:
                return False
            stack.pop()
    return not stack

