def occurance_substring(s: str) -> tuple:
    """Return the substring of `s` that appears in `s` but not in `s`.

    Args:
        s: The input string.

    Returns:
        A tuple (start, end) where start is the first occurrence of `s` and end is the
        last occurrence of `s`. Returns None if no match is found.
    """
    if not s:
        return None
    start = 0
    end = len(s)
    while start < end:
        if s[start] != s[end]:
            return None
        start += 1
        end -= 1
    return (start, end)

def odd_position(numbers):
    """Return True if every odd index contains an odd number of a given list.

    Args:
        numbers: A list of integers.

    Returns:
        True if every odd index contains an odd number of a given list,
        False otherwise.
    """
    odd_positions = []
    for index in range(len(numbers)):
        if index % 2 == 1:
            odd_positions.append(index)
    return len(odd_positions) == len(numbers)

def count_divisors(n: int) -> int:
    """Return the number of divisors of a given integer n.

    Args:
        n: An integer.

    Returns:
        The number of divisors of n.
    """
    if n <= 1:
        return 0
    return 1 + count_divisors(n // 2)

